/// The budget row for a law id, if VISION §4 names one.
pub fn budget(id: &str) -> Option<&'static Budget> {
    BUDGETS.iter().find(|b| b.law == id)
}

/// Find a law by exact id (`L-3`), if it exists.
pub fn find(id: &str) -> Option<&'static Law> {
    LAWS.iter().find(|law| law.id == id)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ids_are_unique_and_well_formed() {
        for (i, law) in LAWS.iter().enumerate() {
            let expected = format!("L-{}", i + 1);
            assert_eq!(
                law.id, expected,
                "ids are contiguous from L-1, never reused"
            );
        }
        let mut seen: Vec<&str> = LAWS.iter().map(|l| l.id).collect();
        let count = seen.len();
        seen.sort_unstable();
        seen.dedup();
        assert_eq!(seen.len(), count);
    }

    #[test]
    fn every_law_names_its_block_and_bound() {
        for law in LAWS {
            assert!(!law.name.is_empty(), "{} has no name", law.id);
            assert!(law.bound.len() > 10, "{} bound is not measurable", law.id);
            assert!(
                law.block.starts_with("Block "),
                "{} must name its enforcing block",
                law.id
            );
        }
    }

    #[test]
    fn lookup_works() {
        assert!(find("L-1").is_some());
        assert!(find("L-99").is_none());
    }

    #[test]
    fn every_budget_names_a_law_that_exists() {
        // A budget pointing at a law id that is not in `LAWS` would render a contract row nobody
        // enforces — the failure D-65 found in prose, prevented here by construction.
        for budget in BUDGETS {
            let law = find(budget.law)
                .unwrap_or_else(|| panic!("budget names {} which is not a law", budget.law));
            assert!(
                !budget.vision.is_empty() && !budget.owes.is_empty(),
                "{} must say what it budgets and what it still owes",
                budget.law
            );
            // The two tables must not disagree about who enforces the number.
            assert!(!law.block.is_empty(), "{} has no block", law.id);
        }
    }

    #[test]
    fn every_budget_is_recorded_once() {
        let mut seen: Vec<&str> = BUDGETS.iter().map(|b| b.law).collect();
        let count = seen.len();
        seen.sort_unstable();
        seen.dedup();
        assert_eq!(seen.len(), count, "a law appears in the budget table twice");
    }

    #[test]
    fn the_budget_table_covers_vision_section_four() {
        // VISION.md §4 lists nine budgets; each one must map to a law. If a budget is added there
        // and not here, this is the test that says so rather than a reader noticing months later.
        assert_eq!(
            BUDGETS.len(),
            9,
            "VISION §4 names nine constitutive budgets"
        );
        // Sorted by the *number*, not the string: "L-10" sorts before "L-2" lexicographically,
        // which the first version of this test got wrong and CI caught.
        let mut laws: Vec<u32> = BUDGETS
            .iter()
            .map(|b| {
                b.law
                    .strip_prefix("L-")
                    .and_then(|n| n.parse().ok())
                    .expect("a law id is L- followed by a number")
            })
            .collect();
        laws.sort_unstable();
        // Every law except L-8 has a VISION §4 budget: L-8 is the geometry invariant, which is a
        // correctness property rather than a budget, and it is claimed by Block 5's gate instead.
        assert_eq!(
            laws,
            vec![1, 2, 3, 4, 5, 6, 7, 9, 10],
            "the budget table must map VISION §4 onto the law table exactly"
        );
    }

    #[test]
    fn an_unmeasured_budget_says_so() {
        // `measured_by: None` is the honest way to record "nothing measures this yet". What is not
        // allowed is a row that has neither a harness nor an admission of what it owes.
        for budget in BUDGETS {
            if let Some(harness) = budget.measured_by {
                assert!(
                    !harness.trim().is_empty(),
                    "{} claims a harness but names none",
                    budget.law
                );
            } else {
                assert!(
                    budget.owes.len() > 20,
                    "{} has no harness and must say what it owes",
                    budget.law
                );
            }
        }
        // Every budget row names a harness as of 2026-11-24 (D-92): L-9 was the last `None`, and it
        // now names `scripts/qualify-l9-portability.sh`, which measures the process half of the law
        // and says `L-9=partial` in its own output. Having a harness is therefore no longer rare
        // enough to be worth counting — but *claiming a law without measuring all of it* is, so
        // that is what this pins instead.
        let unmeasured = BUDGETS.iter().filter(|b| b.measured_by.is_none()).count();
        assert_eq!(
            unmeasured, 0,
            "every budget names a harness as of D-92; if one loses its harness, say so here and in \
             docs/GATES.md's measured column rather than letting the row go quiet"
        );
        let partial = BUDGETS
            .iter()
            .filter(|b| b.measured_by.is_some_and(|h| h.contains("=partial")))
            .map(|b| b.law)
            .collect::<Vec<_>>();
        assert_eq!(
            partial,
            vec!["L-9"],
            "exactly one budget (L-9 portability) is measured only in part; if another becomes \
             partial, name it here and in the prose that ships with it"
        );
    }
}
